package com.fasterxml.jackson.databind.node;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParseException;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.base.ParserMinimalBase;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.IntNode;
import com.fasterxml.jackson.databind.node.LongNode;
import com.fasterxml.jackson.databind.node.NumericNode;
import com.fasterxml.jackson.databind.node.TextNode;
import java.io.*;
import java.io.IOException;
import java.io.OutputStream;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for TreeTraversingParser#getLongValue
 */
public class TreeTraversingParser_getLongValue_TriageGen1Test {

    private ObjectMapper mapper;

    @Before
    public void setUp() {
        mapper = new ObjectMapper();
    }

    @Test
    public void testGetLongValue_WithLongNode() throws IOException {
        long expectedValue = 1234567890123L;
        LongNode longNode = mapper.getNodeFactory().longNode(expectedValue);
        TreeTraversingParser parser = new TreeTraversingParser(longNode);

        // The parser needs to be at the correct token position. 
        // TreeTraversingParser starts at the first node.
        long actualValue = parser.getLongValue();

        assertEquals(expectedValue, actualValue);
    }

    @Test
    public void testGetLongValue_WithIntNode() throws IOException {
        int expectedValue = 42;
        IntNode intNode = mapper.getNodeFactory().numberNode(expectedValue);
        TreeTraversingParser parser = new TreeTraversingParser(intNode);

        long actualValue = parser.getLongValue();

        assertEquals((long) expectedValue, actualValue);
    }

    @Test
    public void testGetLongValue_WithDecimalValue() throws IOException {
        // Testing numeric conversion via NumericNode
        DoubleNode doubleNode = mapper.getNodeFactory().numberNode(123.45);
        TreeTraversingParser parser = new TreeTraversingParser(doubleNode);

        long actualValue = parser.getLongValue();

        // longValue() on a double node truncates
        assertEquals(123L, actualValue);
    }

    @Test(expected = ClassCastException.class)
    public void testGetLongValue_WithNonNumericNode_ThrowsException() throws IOException {
        // TextNode is not a NumericNode, should trigger ClassCastException in the method
        TextNode textNode = mapper.getNodeFactory().textNode("not a number");
        TreeTraversingParser parser = new TreeTraversingParser(textNode);

        parser.getLongValue();
    }

    @Test(expected = JsonParseException.class)
    public void testGetLongValue_WhenCurrentNodeIsNull_ThrowsException() throws IOException {
        // Passing null to constructor or simulating a state where currentNumericNode fails
        // Since we can't easily mock the protected method without PowerMock, 
        // we rely on the provided constructor behavior.
        // If the parser is initialized with a null node or state results in null currentNumericNode
        TreeTraversingParser parser = new TreeTraversingParser(mapper.getNodeFactory().nullNode());

        // nullNode is not a NumericNode
        parser.getLongValue();
    }
}

/**
 * Helper class to allow testing of DoubleNode if not directly accessible via factory in all versions,
 * though mapper.getNodeFactory().numberNode(double) is standard.
 */
class DoubleNode extends NumericNode {
    private final double value;
    public DoubleNode(double value) { super(com.fasterxml.jackson.databind.node.JsonNodeFactory.instance, value); this.value = value; }
    @Override public String toString() { return String.valueOf(value); }
    @Override public com.fasterxml.jackson.core.JsonToken asToken() { return com.fasterxml.jackson.core.JsonToken.VALUE_NUMBER_FLOAT; }
    @Override public long longValue() { return (long) value; }
    @Override public int intValue() { return (int) value; }
    @Override public double doubleValue() { return value; }
    @Override public float floatValue() { return (float) value; }
    @Override public boolean isFloatingPointNumber() { return true; }
    @Override public boolean isIntegralNumber() { return false; }
    @Override public boolean isBoolean() { return false; }
    @Override public boolean isBinary() { return false; }
    @Override public boolean isTextual() { return false; }
    @Override public boolean isNull() { return false; }
    @Override public boolean isObject() { return false; }
    @Override public boolean isArray() { return false; }
    @Override public com.fasterxml.jackson.databind.JsonNode deepCopy() { return new DoubleNode(value); }
    @Override public com.fasterxml.jackson.databind.JavaType getItemType() { return null; }
    @Override public com.fasterxml.jackson.databind.JavaType getElementType() { return null; }
    @Override public com.fasterxml.jackson.databind.JavaType getValueType() { return null; }
}
